MERGE INTO entity_types t USING (SELECT 1 id,'PERSON' n FROM dual UNION ALL SELECT 2,'ORGANIZATION' FROM dual UNION ALL SELECT 3,'ACCOUNT' FROM dual UNION ALL SELECT 4,'DEVICE' FROM dual UNION ALL SELECT 5,'UNKNOWN' FROM dual) s ON(t.entity_type_id=s.id) WHEN MATCHED THEN UPDATE SET t.type_name=s.n WHEN NOT MATCHED THEN INSERT(entity_type_id,type_name) VALUES(s.id,s.n);
MERGE INTO event_types t USING (SELECT 1 id,'INCIDENT' n FROM dual UNION ALL SELECT 2,'LOCATION_OBSERVATION' FROM dual UNION ALL SELECT 3,'ACCESS' FROM dual UNION ALL SELECT 4,'MOVEMENT' FROM dual UNION ALL SELECT 5,'COMMUNICATION' FROM dual UNION ALL SELECT 6,'TRANSACTION' FROM dual UNION ALL SELECT 7,'ALARM' FROM dual UNION ALL SELECT 8,'MEETING' FROM dual UNION ALL SELECT 9,'OTHER' FROM dual) s ON(t.event_type_id=s.id) WHEN MATCHED THEN UPDATE SET t.type_name=s.n WHEN NOT MATCHED THEN INSERT(event_type_id,type_name) VALUES(s.id,s.n);
MERGE INTO relationship_types t USING (SELECT 1 id,'ASSOCIATE' n,0 d FROM dual UNION ALL SELECT 2,'FAMILY',0 FROM dual UNION ALL SELECT 3,'BUSINESS',0 FROM dual UNION ALL SELECT 4,'EMPLOYMENT',1 FROM dual UNION ALL SELECT 5,'TENANCY',1 FROM dual UNION ALL SELECT 6,'CONTACT',1 FROM dual) s ON(t.relationship_type_id=s.id) WHEN MATCHED THEN UPDATE SET t.type_name=s.n,t.is_directional=s.d WHEN NOT MATCHED THEN INSERT(relationship_type_id,type_name,is_directional) VALUES(s.id,s.n,s.d);
MERGE INTO communication_types t USING (SELECT 1 id,'CALL' n FROM dual UNION ALL SELECT 2,'SMS' FROM dual UNION ALL SELECT 3,'EMAIL' FROM dual UNION ALL SELECT 4,'CHAT' FROM dual UNION ALL SELECT 5,'OTHER' FROM dual) s ON(t.communication_type_id=s.id) WHEN MATCHED THEN UPDATE SET t.type_name=s.n WHEN NOT MATCHED THEN INSERT(communication_type_id,type_name) VALUES(s.id,s.n);
MERGE INTO evidence_types t USING (SELECT 1 id,'CCTV' n,0.85 w FROM dual UNION ALL SELECT 2,'DNA',0.95 FROM dual UNION ALL SELECT 3,'FINGERPRINT',0.90 FROM dual UNION ALL SELECT 4,'GPS',0.80 FROM dual UNION ALL SELECT 5,'ACCESS_LOG',0.82 FROM dual UNION ALL SELECT 6,'FINANCIAL',0.75 FROM dual UNION ALL SELECT 7,'COMMUNICATION',0.65 FROM dual UNION ALL SELECT 8,'WITNESS',0.55 FROM dual UNION ALL SELECT 9,'DIGITAL',0.70 FROM dual UNION ALL SELECT 10,'DOCUMENT',0.60 FROM dual) s ON(t.evidence_type_id=s.id) WHEN MATCHED THEN UPDATE SET t.type_name=s.n,t.base_weight=s.w WHEN NOT MATCHED THEN INSERT(evidence_type_id,type_name,base_weight) VALUES(s.id,s.n,s.w);
COMMIT;
